import {advanceFarm} from './farm.mjs';
export const WEATHER=['clear','cloudy','rain','snow'];
export function freshEnvironment(){return{minute:480,age:0,weather:'clear',previous:'clear',transition:1,seed:7183};}
export function validEnvironment(e){return e&&Number.isFinite(e.minute)&&e.minute>=0&&e.minute<1440&&Number.isFinite(e.age)&&e.age>=0&&e.age<=360&&WEATHER.includes(e.weather)&&WEATHER.includes(e.previous)&&Number.isFinite(e.transition)&&e.transition>=0&&e.transition<=1&&Number.isSafeInteger(e.seed)&&e.seed>=0&&e.seed<=4294967295;}
export function stepEnvironment(state,dt){const e=state.environment;if(!Number.isFinite(dt)||dt<=0)return;dt=Math.min(dt,1);e.minute+=dt*1440/1800;if(e.minute>=1440){e.minute-=1440;if(state.day<100000){state.day++;advanceFarm(state);if(state.activities?.camp)state.activities.camp.fire=false;}}e.age+=dt;e.transition=Math.min(1,e.transition+dt/18);if(e.age>=300){e.age=0;e.previous=e.weather;e.seed=(Math.imul(e.seed,1664525)+1013904223)>>>0;const r=e.seed/4294967296;e.weather=r<.42?'clear':r<.72?'cloudy':r<.94?'rain':'snow';e.transition=0;}}
export function environmentLight(e,altitude=0){const sun=Math.sin((e.minute/1440-.25)*Math.PI*2),day=Math.max(0,Math.min(1,(sun+.12)/.5));const wet=w=>w==='rain'?1:w==='snow'?.75:w==='cloudy'?.45:0,cloud=wet(e.previous)+(wet(e.weather)-wet(e.previous))*e.transition;const cold=altitude>45;
 return{sun,day,cloud,rain:e.weather==='rain'&&!cold?e.transition:e.previous==='rain'&&!cold?1-e.transition:0,snow:(e.weather==='snow'||e.weather==='rain'&&cold)?e.transition:(e.previous==='snow'||e.previous==='rain'&&cold)?1-e.transition:0,night:1-day,label:String(Math.floor(e.minute/60)).padStart(2,'0')+':'+String(Math.floor(e.minute%60)).padStart(2,'0')};}
